import collections
batches=json.load(open(BASE+"/batches.json"))
want=[]
for k in ("B10","B11","B12"): want+=batches[k]
assert len(E)==60, len(E)
assert [e[0] for e in E]==want, "id order/set mismatch"
os.makedirs(OUT,exist_ok=True)
for cid,conf,tr,reason,pred,body in E:
    doc={"case_id":cid,"prediction_text":pred,
         "basis":"liuyao\n"+body,"confidence":conf,
         "trigger":{"changed_main":tr[0],"reserve_used":tr[1],"disputed":tr[2],"reason":reason}}
    with open(f"{OUT}/{cid}.json","w",encoding="utf-8") as f:
        json.dump(doc,f,ensure_ascii=False,indent=1)
# verify per-id exact open
cnt=collections.Counter()
for cid in want:
    d=json.load(open(f"{OUT}/{cid}.json"))
    assert d["case_id"]==cid and d["basis"].splitlines()[0]=="liuyao"
    t=d["trigger"]
    for i,k in enumerate(("changed_main","reserve_used","disputed")):
        if t[k]: cnt[k]+=1
print("WROTE",len(want),dict(cnt))
for cid in want:
    print(cid, os.path.getsize(f"{OUT}/{cid}.json"))
